'use strict';
const $ = (s, root=document) => root.querySelector(s);
const esc = v => String(v ?? '').replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names = {overview:'운영 현황', ledger:'USB 허용 원장',register:'승인 정보 등록',deployment:'정책 배포 관리',pcs:'PC 관리',history:'변경 이력'};
const status = {active:['유효 허용','green'],deployment_pending:['배포 대기','blue'],verification_pending:['검증 대기','amber'],expired:['만료',''],revoked:['회수',''],rejected:['반려','red']};
const deployment = {device_applied:['단말 적용 확인','green'],publish_pending:['정책 게시 대기','blue'],publish_failed:['정책 게시 실패','red'],published:['모의 게시 · 적용 대기','purple'],withdrawal_pending:['회수 반영 대기','amber'],withdrawal_published:['모의 회수 게시 · 확인 대기','purple'],withdrawal_confirmed:['회수 확인',''],not_published:['미게시','']};
const validation = {verified:'식별 검증 완료',encryption_pending:'암호화 확인 필요',multiple_candidates:'복수 후보 확인 필요',not_observed:'관측 기록 없음'};
deployment.sample_group_managed=['샘플 그룹 자동 처리','blue'];
const events = {sample_group_sync:'실제 샘플 그룹 반영',registered:'승인 정보 접수',device_applied:'단말 적용 확인',verify:'모의 식별 검증',extend:'사용 기간 연장',revoke:'허용 회수',confirm_device:'모의 단말 확인',simulated_publish:'모의 정책 게시',pc_classification:'PC 분류 변경'};
let state, plan, identity, jobsState, labState, sampleMappings=[], jobRefreshBusy=false, page=1, filter='all', term='', historyTerm='', dept='', currentView='overview';
names.sample='테넌트 샘플 검증';
names.pairs='페어링 정책';
names.requests='처리 요청';
let cloudRequests;
class QueuedRequest extends Error {}
async function queuedNotice(error){if(!(error instanceof QueuedRequest))return false;if(dialog.open)dialog.close();location.hash='requests';await render();toast(error.message);return true;}
function requestsView(){return header('requests')+`<section class="panel"><h2>노트북 처리 요청</h2><p>파일 접수는 원장 변경 완료와 다릅니다. 정기 노트북의 처리 결과를 확인하세요.</p><button data-action="refresh">새로 고침</button><div class="table-wrap"><table><thead><tr><th>접수 시각</th><th>처리 경로</th><th>상태</th><th>결과</th></tr></thead><tbody>${(cloudRequests?.requests||[]).map(r=>`<tr><td>${timeText(r.created_at)}</td><td>${esc(r.path)}</td><td>${esc(({queued:'노트북 처리 대기',completed:'처리 완료',rejected:'처리 거부'})[r.status]||r.status)}</td><td><pre>${esc(JSON.stringify(r.result??r.detail??'',null,2))}</pre></td></tr>`).join('')||'<tr><td colspan="4">접수된 요청이 없습니다.</td></tr>'}</tbody></table></div></section>`;}

let pairPolicyState;
const dialog = $('#dialog');
function badge(key, map=status){const [label,color] = map[key] || [key||'미확인',''];return `<span class="badge ${color}">${esc(label)}</span>`;}
function permission(r){return r.permission==='read_write'?'읽기 · 쓰기':'읽기 전용';}
function dayDelta(d){return Math.round((new Date(d+'T00:00:00Z')-new Date(state.reference_date+'T00:00:00Z'))/86400000);}
function valid(r){return ['active','deployment_pending'].includes(r.approval_status) && r.valid_from_date<=state.reference_date && r.valid_until_date>=state.reference_date && r.validation_status==='verified' && (r.permission!=='read_write'||r.bitlocker_state==='encrypted');}
function dateText(v){return v?esc(v.slice(0,10).replaceAll('-','.')):'—';}
function timeText(v){if(!v)return '—';return new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Seoul',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(v));}
function count(key){return state.approvals.filter(r=>r.approval_status===key).length;}
function toast(message,error=false){const t=$('#toast');t.textContent=message;t.className='show'+(error?' error':'');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.className='',5000);}
async function api(path, body){const response=await fetch(path,body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json','X-Local-Demo':'1','Idempotency-Key':crypto.randomUUID()},body:JSON.stringify(body)});if(!response.ok){let error;try{error=await response.json();}catch{throw new Error(`서버 요청에 실패했습니다 (HTTP ${response.status}). 연결 상태와 설정을 확인해 주세요.`);}const detail=error?.detail;throw new Error(Array.isArray(detail)?detail.map(e=>`${e.loc.at(-1)}: ${e.msg}`).join(' / '):detail||`요청에 실패했습니다 (HTTP ${response.status}).`);}const value=await response.json();if(response.status===202&&value.accepted){throw new QueuedRequest(value.message);}return value;}
async function load(){identity=await api('/api/me');applyIdentity();state=await api('/api/state');$('#nav-count').textContent=state.approvals.length;$('#footer-date').textContent=`데이터 기준 ${state.reference_date} · ${state.mode==='azure_functions'?'레이크하우스 파일 저장':'로컬 저장'}`;document.querySelector('[data-view="requests"]').hidden=state.mode!=='azure_functions';if(state.mode==='azure_functions'){document.querySelector('.workspace small').textContent='Fabric 정기 처리';document.querySelector('.sidebar-bottom .connection').innerHTML='<span class="dot"></span>레이크하우스 연동';document.querySelector('footer span').textContent='USB CONTROL · Azure 테스트';document.querySelector('.sidebar-bottom p').textContent='파일 접수 후 노트북 처리 결과를 확인하세요.';}}
function header(view,actions=''){return `<div class="page-head"><div><h1>${names[view]}</h1><p>${({requests:'접수된 파일 요청과 정기 노트북의 처리 결과를 확인합니다.',overview:'사용자–USB 허용 상태와 처리할 작업을 한눈에 확인하세요.',ledger:'그룹웨어 승인 결과를 기준으로 사용자와 USB의 연결을 관리합니다.',register:'결재가 완료된 승인 정보를 등록하고 식별 검증을 시작합니다.',deployment:'유효한 사용자–USB 조합과 회수 대상을 게시 전에 확인합니다.',pcs:'예외 허용 대상과 공용 PC 제외 범위를 관리합니다.',history:'등록부터 회수까지 변경 근거와 처리 결과를 확인합니다.'})[view]}</p></div><div class="head-actions">${actions}</div></div>`;}
function notice(){if(state?.mode==='azure_functions')return `<div class="notice"><span>ⓘ</span><span><b>레이크하우스 예약 처리</b> · 변경 요청은 파일로 접수한 뒤 정기 노트북이 처리합니다. 처리 요청 화면에서 완료 여부를 확인하세요. 실제 단말 적용은 별도입니다.</span></div>`;return `<div class="notice"><span>ⓘ</span><span><b>샘플 검증</b> · 원장은 로컬에 저장합니다. 승인된 페어링은 자동 갱신이 활성화된 샘플 Intune 정책에 반영될 수 있습니다. 실제 단말 적용과 USB 동작은 별도 확인이 필요합니다.</span><span class="date">데모 기준일 ${dateText(state.reference_date)}</span></div>`;}
function filtersHTML(){const departments=[...new Set(state.approvals.map(r=>r.department))].sort();return `<div class="filters"><label class="search"><span>⌕</span><input id="search" type="search" aria-label="원장 검색" placeholder="사용자, USB 시리얼, 기안번호 검색" value="${esc(term)}"></label><select id="dept" aria-label="부서 필터"><option value="">모든 부서</option>${departments.map(d=>`<option ${dept===d?'selected':''}>${esc(d)}</option>`).join('')}</select><button class="subtle-button" data-action="clear-filters">필터 초기화</button></div>`;}
function filtered(){return state.approvals.filter(r=>{
  const matches=filter==='all'||filter==='followup'&&['publish_pending','publish_failed','withdrawal_pending','published','withdrawal_published'].includes(r.deployment_status)||r.approval_status===filter||filter==='valid'&&valid(r)||filter==='expiring'&&valid(r)&&dayDelta(r.valid_until_date)<=7||filter==='failed'&&r.deployment_status==='publish_failed';
  return matches&&(!dept||dept===r.department)&&(!term||[r.user_display_name,r.user_upn,r.usb_serial,r.approval_document_no,r.department].join(' ').toLowerCase().includes(term.toLowerCase()));
});}
function table(rows, compact=false){return `<div class="table-wrap"><table><thead><tr><th>사용자 / 부서</th><th>USB / 권한</th><th>허용 기간</th><th>원장 상태</th><th>배포 상태</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td><button class="row-link person" data-action="detail" data-id="${esc(r.approval_id)}">${esc(r.user_display_name)}</button><span class="cell-sub">${esc(r.department)}</span></td><td><span class="mono">${esc(r.usb_serial)}</span><span class="cell-sub">${permission(r)}${r.permission==='read_write'?' · 암호화 필수':''}</span></td><td>${dateText(r.valid_until_date)}<span class="cell-sub">${dayDelta(r.valid_until_date)<0?'기간 종료':dayDelta(r.valid_until_date)===0?'오늘 만료':`D−${dayDelta(r.valid_until_date)}`} · ${dateText(r.valid_from_date)}부터</span></td><td>${badge(r.approval_status)}${!compact?`<span class="cell-sub">${esc(validation[r.validation_status]||r.validation_status)}</span>`:''}</td><td>${badge(r.deployment_status,deployment)}${linkedGroupBadge(r)}</td><td><button class="row-button" data-action="detail" data-id="${esc(r.approval_id)}">상세 보기</button></td></tr>`).join('')||`<tr><td colspan="6"><div class="empty"><strong>조회 결과가 없습니다</strong>검색어나 필터를 바꿔 주세요.</div></td></tr>`}</tbody></table></div>`;}
function overview(){const validRows=state.approvals.filter(valid);const expiring=validRows.filter(r=>dayDelta(r.valid_until_date)<=7);const waiting=state.approvals.filter(r=>['publish_pending','publish_failed','withdrawal_pending','published','withdrawal_published'].includes(r.deployment_status));const failed=state.approvals.filter(r=>r.deployment_status==='publish_failed').length;
 const cards=[['유효한 허용 조합',validRows.length,`${count('active')}건 단말 적용 확인 · 샘플 기준`,'◎','valid'],['식별 검증 대기',count('verification_pending'),'시리얼·관측 정보 확인 필요','⌕','verification_pending'],['배포 후속 작업',waiting.length,`게시 실패 ${failed}건 포함 · 모의 처리`,'⇧','followup'],['7일 이내 만료',expiring.length,'승인 연장 또는 회수 검토','◷','expiring']];
 const attention=[...state.approvals.filter(r=>r.deployment_status==='publish_failed'),...expiring,...state.approvals.filter(r=>r.approval_status==='verification_pending')].slice(0,5);
 return header('overview','<button class="subtle-button" data-action="export">↓ CSV 내보내기</button><button class="primary subtle-button" data-action="go" data-view="register">＋ 승인 정보 등록</button>')+notice()+`<section class="stats">${cards.map(([label,value,note,icon,f])=>`<button class="stat" data-action="metric" data-filter="${f}"><span class="label">${label}</span><span class="mini-icon">${icon}</span><span class="value">${value}<span class="unit">건</span></span><span class="note">${note}</span></button>`).join('')}</section><div class="overview-grid"><section class="panel"><div class="panel-head"><h2>원장 상태 분포</h2><span class="cell-sub">전체 ${state.approvals.length}건</span></div><div class="distribution">${['active','deployment_pending','verification_pending','expired','revoked','rejected'].map((k,i)=>`<div class="distribution-row"><span class="name">${status[k][0]}</span><progress class="bar-progress ${['green','blue','amber','grey','grey','red'][i]}" max="${state.approvals.length}" value="${count(k)}">${count(k)}</progress><b>${count(k)}</b><span class="cell-sub">건</span></div>`).join('')}</div></section><section class="panel"><div class="panel-head"><h2>최근 변경 이력</h2><button class="text-link" data-action="go" data-view="history">전체 보기 →</button></div><div class="activity-list">${state.history.slice(0,4).map(h=>`<div class="activity"><span class="activity-dot"></span><div><span class="title">${esc(events[h.event_type]||h.description)}</span><small>${esc(h.approval_id)} · ${esc(h.actor_upn.split('@')[0])}</small></div><time>${timeText(h.event_at_utc)}</time></div>`).join('')}</div></section></div><section class="panel"><div class="panel-head"><div><h2>확인이 필요한 항목<span class="section-count">${attention.length}</span></h2><p>게시 실패와 만료 예정, 식별 검증 대기 건을 우선 확인하세요.</p></div><button class="text-link" data-action="go" data-view="ledger">원장 전체 보기 →</button></div>${table(attention,true)}</section>`;
}
function ledger(){const rows=filtered();const pages=Math.max(1,Math.ceil(rows.length/10));page=Math.min(page,pages);return header('ledger','<button class="subtle-button" data-action="export">↓ 필터 결과 CSV</button><button class="primary subtle-button" data-action="go" data-view="register">＋ 승인 정보 등록</button>')+notice()+`<section class="panel"><div class="status-tabs">${['all','valid','followup',...Object.keys(status),'expiring','failed'].map(k=>`<button data-action="filter" data-filter="${k}" class="${filter===k?'active':''}">${k==='all'?'전체':k==='valid'?'유효 조합':k==='followup'?'배포 후속':k==='expiring'?'7일 이내 만료':k==='failed'?'게시 실패':status[k][0]}<small>${k==='all'?state.approvals.length:status[k]?count(k):''}</small></button>`).join('')}</div>${filtersHTML()}<div id="ledger-results">${ledgerResults(rows,pages)}</div></section>`;}
function ledgerResults(rows=filtered(),pages=Math.max(1,Math.ceil(rows.length/10))){page=Math.min(page,pages);return table(rows.slice((page-1)*10,page*10))+`<div class="table-foot"><span>전체 ${rows.length}건${rows.length?` 중 ${(page-1)*10+1}–${Math.min(page*10,rows.length)}건`:''}</span><div class="pagination"><button data-action="page" data-page="${page-1}" ${page===1?'disabled':''}>‹ 이전</button>${Array.from({length:pages},(_,i)=>`<button data-action="page" data-page="${i+1}" class="${page===i+1?'current':''}">${i+1}</button>`).join('')}<button data-action="page" data-page="${page+1}" ${page===pages?'disabled':''}>다음 ›</button></div></div>`;}
function field(label,name,type='text',placeholder='',full=false){return `<label class="field ${full?'full':''}"><span>${label}<em>*</em></span><input name="${name}" type="${type}" placeholder="${esc(placeholder)}" required ${type==='text'?'maxlength="150"':''}></label>`;}
function registration(){return header('register','<button class="subtle-button" data-action="fill-sample">가상 예시 채우기</button>')+notice()+`<form id="register-form" class="panel form-panel"><div class="form-section"><h2><span class="step-number">1</span>승인 사용자</h2><p>그룹웨어에서 결재가 완료된 사용자 정보를 입력하세요. 이 화면에서는 결재를 진행하지 않습니다.</p><div class="form-grid">${field('사용자 이름','user_display_name','text','예: 김샘플')}${field('사용자 계정','user_upn','email','sample.new@example.invalid')}${field('부서','department','text','예: 정보보안팀')}<div class="field-note">현재는 가상 계정만 등록할 수 있습니다.<br>@example.invalid 도메인을 사용해 주세요.</div></div></div><div class="form-section"><h2><span class="step-number">2</span>USB 및 허용 범위</h2><p>승인 사용자와 USB를 하나의 조합으로 등록합니다. 특정 PC에만 허용을 제한하는 설정은 아닙니다.</p><div class="form-grid">${field('USB 시리얼','usb_serial','text','SAMPLE-NEW-0001')}${field('USB 이름','usb_name','text','예: 가상 보안 USB')}<label class="field"><span>사용 권한<em>*</em></span><select name="permission"><option value="read_only">읽기 전용</option><option value="read_write">읽기 · 쓰기 (BitLocker 암호화 필수)</option></select></label><label class="field"><span>암호화 확인 상태<em>*</em></span><select name="bitlocker_state"><option value="encrypted">암호화 확인</option><option value="unknown">확인되지 않음</option><option value="not_encrypted">암호화되지 않음</option></select></label>${field('사용 시작일','valid_from_date','date')}${field('사용 종료일','valid_until_date','date')}</div></div><div class="form-section"><h2><span class="step-number">3</span>승인 근거</h2><p>기안번호와 사유는 등록·변경 이력에 함께 보관됩니다.</p><div class="form-grid">${field('그룹웨어 기안번호','approval_document_no','text','예: SAMPLE-GW-2026-0041',true)}<label class="field full"><span>사용 사유<em>*</em></span><textarea name="request_reason" required minlength="3" maxlength="500" placeholder="승인된 업무 목적을 입력해 주세요."></textarea></label></div></div><div class="form-actions"><div id="register-error" class="form-message" role="alert"></div><button type="reset">입력 초기화</button><button type="submit" class="primary">승인 정보 등록</button></div><div class="callout">등록 후에는 식별 검증 대기로 저장됩니다. 접수 완료가 정책 게시나 단말 허용 완료를 의미하지 않습니다.</div></form>`;}
function deploymentView(){return header('deployment','<button class="subtle-button" data-action="refresh">↻ 미리보기 갱신</button>')+notice()+`<div class="split"><div><section class="panel"><div class="panel-head"><div><h2>변경 사항 미리보기</h2><p>검증된 유효 승인만 포함하며, 사용자–USB의 연결을 유지합니다.</p></div>${badge('모의 처리')}</div><div class="preview-metrics"><div><small>유효 허용 조합</small><b>${plan.pairs.length}<span class="unit"> 건</span></b></div><div><small>신규 / 변경 게시</small><b>${plan.pending.length}<span class="unit"> 건</span></b></div><div><small>회수 게시</small><b>${plan.withdrawals.length}<span class="unit"> 건</span></b></div></div><div class="detail-grid"><div><small>미리보기에서 제외</small><strong>${plan.excluded}건 · 검증 대기 / 기간 외 / 종료 상태</strong></div><div><small>대상 PC</small><strong>${plan.target_pcs.length}대 · 예외 허용 분류</strong></div><div><small>미리보기 JSON 크기</small><strong>${plan.manifest_bytes.toLocaleString()} bytes</strong></div><div><small>프로필 분할 검사</small><strong>미연결 · XML 생성 이후 산정</strong></div></div><div class="modal-actions"><button class="primary" data-action="publish" ${plan.pending.length+plan.withdrawals.length===0?'disabled':''}>변경 ${plan.pending.length+plan.withdrawals.length}건 모의 게시</button></div><div class="callout">모의 게시 후에도 단말 적용은 대기 상태로 남습니다. 실제 Device Control XML 생성, Intune 게시, 단말 증거 수집은 연결되지 않았습니다.</div></section><section class="panel"><div class="panel-head"><h2>게시할 변경 목록</h2></div>${table(state.approvals.filter(r=>plan.pending.includes(r.approval_id)||plan.withdrawals.includes(r.approval_id)),true)}</section></div><aside><section class="panel"><div class="panel-head"><h2>처리 단계</h2></div><div class="info-body"><ol><li><strong>승인 정보 접수</strong><br>그룹웨어 기안번호와 승인 내용을 보관합니다.</li><li><strong>식별 검증 · 원장 변경</strong><br>사용자와 USB 조합, 기간과 암호화 상태를 확인합니다.</li><li><strong>정책 게시</strong><br>허용과 회수를 구분해 변경을 게시합니다.</li><li><strong>단말 확인</strong><br>정책 게시와 실제 단말 적용 결과를 따로 추적합니다.</li></ol></div></section><section class="panel"><div class="panel-head"><h2>기본 통제</h2></div><div class="info-body">공용·미분류 PC는 예외 허용 대상에서 제외됩니다.<br><br><strong>기본 USB 차단과 BitLocker 쓰기 제한은 계속 유지합니다.</strong></div></section></aside></div>`;}
function pcsView(){const assignment={allowed:['예외 허용 대상','green'],excluded:['공용 PC 제외',''],unclassified:['분류 대기','amber']};return header('pcs')+notice()+`<section class="panel"><div class="panel-head"><div><h2>관리 대상 PC<span class="section-count">${state.pcs.length}대</span></h2><p>분류 변경과 그룹 반영, 기존 허용 정책 제거 확인은 별도 상태입니다.</p></div></div><div class="table-wrap"><table><thead><tr><th>PC / 부서</th><th>용도</th><th>예외 분류</th><th>기본 차단 / 암호화 정책</th><th>그룹 반영 / 허용 제거</th><th></th></tr></thead><tbody>${state.pcs.map(p=>`<tr><td><span class="person">${esc(p.device_name)}</span><span class="cell-sub">${esc(p.department)}</span></td><td>${esc(p.device_purpose)}</td><td>${badge(p.exception_assignment,assignment)}<span class="cell-sub">${esc(p.exclusion_reason)}</span></td><td>${p.baseline_block_required?'기본 차단 유지':'확인 필요'}<span class="cell-sub">${p.bitlocker_policy_required?'BitLocker 정책 필수':'확인 필요'}</span></td><td>${p.group_sync_status==='synced'?'그룹 반영 확인':'그룹 반영 대기'}<span class="cell-sub">${({not_required:'허용 제거 불필요',confirmed:'허용 제거 확인',confirmation_pending:'허용 제거 확인 대기',pending:'허용 제거 대기',withdrawal_pending:'허용 제거 대기'})[p.withdrawal_status]||esc(p.withdrawal_status)}</span></td><td><button class="row-button" data-action="pc" data-id="${esc(p.device_id)}">분류 변경</button></td></tr>`).join('')}</tbody></table></div><div class="callout">예외 분류를 변경해도 실제 장치 그룹은 변경되지 않습니다. 공용 PC 전환 시 기존 허용 제거는 확인 대기로 남습니다.</div></section>`;}
function historyView(){const rows=state.history.filter(h=>!historyTerm||[h.approval_id,h.description,h.user_upn,h.actor_upn].join(' ').toLowerCase().includes(historyTerm.toLowerCase()));const pages=Math.max(1,Math.ceil(rows.length/15));page=Math.min(page,pages);return header('history')+notice()+`<section class="panel"><div class="filters"><label class="search"><span>⌕</span><input id="history-search" type="search" aria-label="이력 검색" placeholder="등록 ID, 계정, 처리 사유 검색" value="${esc(historyTerm)}"></label><span class="cell-sub">${rows.length}건 · 최신순 · KST</span></div><div class="table-wrap"><table><thead><tr><th>처리 시각 (KST)</th><th>변경 유형 / 대상</th><th>변경 내용</th><th>처리자</th><th></th></tr></thead><tbody>${rows.slice((page-1)*15,page*15).map(h=>`<tr><td>${timeText(h.event_at_utc)}</td><td><span class="person">${esc(events[h.event_type]||h.event_type)}</span><span class="cell-sub">${esc(h.approval_id)}</span></td><td class="history-desc">${esc(h.description)}<span class="cell-sub">${esc(status[h.old_status]?.[0]||h.old_status||'접수 전')} → ${esc(status[h.new_status]?.[0]||h.new_status)}</span></td><td>${esc(h.actor_upn.split('@')[0])}</td><td><button class="row-button" data-action="event" data-id="${esc(h.event_id)}">상세</button></td></tr>`).join('')||'<tr><td colspan="5"><div class="empty">일치하는 이력이 없습니다.</div></td></tr>'}</tbody></table></div><div class="table-foot"><span>변경 이력은 로컬에 보관됩니다.</span><div class="pagination"><button data-action="history-page" data-page="${page-1}" ${page<=1?'disabled':''}>‹ 이전</button><span>${page} / ${pages}</span><button data-action="history-page" data-page="${page+1}" ${page>=pages?'disabled':''}>다음 ›</button></div></div></section>`;}
let renderSequence=0;
async function render(){
 const expectedSequence=renderSequence+1;
 try{await renderView();}
 catch(error){if(expectedSequence!==renderSequence)return;$('#main').innerHTML=header(currentView)+`<section class="panel"><div class="empty"><strong>화면을 불러오지 못했습니다</strong><p>${esc(error.message)}</p><button class="secondary" data-action="refresh">다시 불러오기</button></div></section>`;throw error;}
}
async function renderView(){const sequence=++renderSequence;currentView=location.hash.slice(1)||'overview';if(!names[currentView])currentView='overview';$('#crumb').textContent=names[currentView];document.title=`${names[currentView]} · USB 운영 콘솔`;$('nav').querySelectorAll('a').forEach(a=>{const active=a.dataset.view===currentView;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});if(currentView==='requests'){cloudRequests=await api('/api/cloud-requests');if(sequence!==renderSequence)return;}if(currentView==='deployment'){const loaded=await Promise.all([api('/api/deployment/preview'),api('/api/jobs')]);if(sequence!=renderSequence||currentView!='deployment')return;[plan,jobsState]=loaded;}if(currentView==='register'&&identity.mode==='entra'){sampleMappings=(await api('/api/sample-directory/mappings')).users;if(sequence!==renderSequence)return;}if(currentView==='pairs'){pairPolicyState=await api('/api/pair-policy');if(sequence!==renderSequence||currentView!=='pairs')return;}if(currentView==='sample'){labState=await api('/api/sample-directory');if(sequence!==renderSequence||currentView!=='sample')return;}$('#main').innerHTML=({overview,ledger,register:registration,deployment:deploymentView,pcs:pcsView,history:historyView,sample:sampleView,pairs:pairPolicyView,requests:requestsView})[currentView]();if(currentView==='deployment')$('#main').insertAdjacentHTML('beforeend',jobsPanel());if(currentView==='register')$('#main').insertAdjacentHTML('afterbegin',liveLookupPanel()+sampleRegistrationPanel());applyPermissions();}
function dialogHeader(title,sub=''){return `<div class="dialog-header"><div><h2 id="dialog-title">${esc(title)}</h2>${sub?`<small>${esc(sub)}</small>`:''}</div><button data-action="close" aria-label="닫기">×</button></div>`;}
function openDialog(html){delete dialog.dataset.groupLedgerId;$('#dialog-body').innerHTML=html;if(!dialog.open)dialog.showModal();applyPermissions();}
function detail(id){const r=state.approvals.find(r=>r.approval_id===id);if(!r)return;const history=state.history.filter(h=>h.approval_id===id).slice(0,6);openDialog(dialogHeader(r.user_display_name+' · USB 허용 상세',r.approval_id)+`<div class="detail-grid"><div><small>사용자 계정 / 부서</small><strong>${esc(r.user_upn)}<br>${esc(r.department)}</strong></div><div><small>USB 시리얼 / 이름</small><strong>${esc(r.usb_serial)}<br>${esc(r.usb_name)}</strong></div><div><small>허용 기간 / 권한</small><strong>${dateText(r.valid_from_date)} – ${dateText(r.valid_until_date)}<br>${permission(r)}</strong></div><div><small>암호화 / 식별 검증</small><strong>${({encrypted:'암호화 확인',not_encrypted:'암호화되지 않음',unknown:'미확인'})[r.bitlocker_state]}<br>${esc(validation[r.validation_status])}</strong></div><div><small>승인 근거</small><strong>${esc(r.approval_document_no)}</strong></div><div><small>관측 PC / 관측 시각</small><strong>${esc(r.last_observed_pc||'관측 없음')}<br>${timeText(r.last_observed_at_utc)}</strong></div><div><small>원장 상태</small>${badge(r.approval_status)}</div><div><small>배포 상태</small>${badge(r.deployment_status,deployment)}</div><div><small>원장 / 배포 버전</small><strong>v${r.ledger_version} / v${r.deployment_version} · 로컬 사본</strong></div><div><small>정책 프로필</small><strong>${esc(r.policy_profile_name||'매핑 없음')}</strong></div><div class="full"><small>사용 사유</small><strong>${esc(r.request_reason)}</strong></div>${r.revocation_reason?`<div class="full"><small>회수 사유</small><strong>${esc(r.revocation_reason)}</strong></div>`:''}${r.last_error?`<div class="full danger"><small>마지막 오류</small><strong>${esc(r.last_error)}</strong></div>`:''}</div><div class="stage-strip"><span class="done">승인 접수</span><span class="${r.validation_status==='verified'?'done':''}">식별 검증</span><span class="${['device_applied','published','withdrawal_published','withdrawal_confirmed'].includes(r.deployment_status)?'done':''}">정책 게시</span><span class="${['device_applied','withdrawal_confirmed'].includes(r.deployment_status)?'done':''}">단말 확인</span></div><div class="timeline"><h3>최근 변경 이력</h3>${history.map(h=>`<div class="timeline-item">${esc(h.description)}<small>${timeText(h.event_at_utc)} · ${esc(h.actor_upn)}</small></div>`).join('')}</div><div class="modal-actions">${r.approval_status==='verification_pending'?`<button data-action="change" data-kind="verify" data-id="${esc(id)}">모의 식별 검증</button>`:''}${['active','deployment_pending'].includes(r.approval_status)?`<button data-action="change" data-kind="extend" data-id="${esc(id)}">사용 기간 연장</button>`:''}${['published','withdrawal_published'].includes(r.deployment_status)?`<button data-action="change" data-kind="confirm_device" data-id="${esc(id)}">모의 단말 확인</button>`:''}${['active','deployment_pending','verification_pending'].includes(r.approval_status)?`<button class="danger" data-action="change" data-kind="revoke" data-id="${esc(id)}">허용 회수</button>`:''}<button data-action="close">닫기</button></div>`);sampleLedgerDetail(r);}
function changeForm(id,kind){const r=state.approvals.find(r=>r.approval_id===id);const title={verify:'모의 식별 검증',extend:'사용 기간 연장',revoke:'USB 허용 회수',confirm_device:'모의 단말 확인'}[kind];openDialog(dialogHeader(title,r.user_display_name+' · '+r.usb_serial)+`<form id="change-form" class="dialog-form" data-id="${esc(id)}" data-kind="${kind}" data-revision="${r.revision}"><div class="dialog-info">${r.sample_group_key?'실제 샘플 그룹 연결 테스트입니다. SID 조회는 완료 가정이며 USB 동작과 단말 적용은 검증하지 않습니다. 원장 변경 후 Function이 샘플 그룹을 자동 처리합니다.':({verify:'데모용 식별 검증입니다. 실제 Defender 관측값이나 사용자 식별값을 확인한 결과가 아닙니다. 읽기·쓰기는 암호화 상태가 확인된 경우에만 처리합니다.',extend:'그룹웨어에서 연장 승인이 완료된 기안번호를 기록하세요. 변경 후 정책 게시 대기로 전환됩니다.',revoke:'원장에서는 허용을 종료합니다. 이미 게시된 건은 정책 회수와 단말 제거 확인이 완료될 때까지 별도로 추적합니다.',confirm_device:'데모용 단말 확인 기록입니다. 실제 PC의 정책 적용·회수 또는 USB 사용을 확인한 결과가 아닙니다.'})[kind]}</div>${kind==='extend'?`${field('새 종료일','valid_until_date','date')}${field('연장 승인 기안번호','approval_document_no','text','SAMPLE-GW-EXT-2026-0001')}`:''}<label class="field"><span>처리 사유<em>*</em></span><textarea name="reason" minlength="3" maxlength="500" required placeholder="변경 근거와 처리 사유를 입력해 주세요."></textarea></label><div class="form-error" role="alert"></div><div class="form-actions"><button type="button" data-action="detail" data-id="${esc(id)}">돌아가기</button><button type="submit" class="primary">${title} 기록</button></div></form>`);if(kind==='extend'){$('[name=valid_until_date]',dialog).min=new Date(new Date(r.valid_until_date+'T00:00:00Z').getTime()+86400000).toISOString().slice(0,10);}}
function pcForm(id){const p=state.pcs.find(p=>p.device_id===id);openDialog(dialogHeader('PC 예외 분류 변경',p.device_name)+`<form id="pc-form" class="dialog-form" data-id="${esc(id)}" data-revision="${p.revision}"><div class="dialog-info">기본 차단과 BitLocker 정책은 유지됩니다. 실제 그룹 반영과 기존 허용 제거는 대기 상태로 기록됩니다.</div><label class="field"><span>예외 허용 분류</span><select name="assignment"><option value="allowed">예외 허용 대상</option><option value="excluded">공용 PC 제외</option><option value="unclassified">분류 대기</option></select></label><label class="field"><span>변경 사유</span><textarea name="reason" required minlength="3" maxlength="500"></textarea></label><div class="form-error" role="alert"></div><div class="form-actions"><button type="button" data-action="close">취소</button><button type="submit" class="primary">분류 변경 기록</button></div></form>`);$('[name=assignment]',dialog).value=p.exception_assignment;}
async function doAction(el){const a=el.dataset.action;const id=el.dataset.id;
 if(a==='close')dialog.close();
 else if(a==='pair-publish'){el.disabled=true;try{await api('/api/pair-policy/publish',{version:pairPolicyState.version});await render();toast('샘플 정책 XML 저장과 재조회를 확인했습니다.');}finally{el.disabled=false;}}
 else if(a==='fill-linked-sample')fillLinkedSample();
 else if(a==='sample-sync'){el.disabled=true;try{await api('/api/sample-directory/sync',{});await load();await render();if(id)detail(id);toast('연결된 승인 원장의 그룹 반영 결과를 확인했습니다.');}finally{el.disabled=false;}}
 else if(a==='sample-change')sampleForm(id,el.dataset.kind);
 else if(a==='sample-expiry'){el.disabled=true;try{await api('/api/sample-directory/expiry',{});await render();toast('샘플 승인 만료와 미완료 회수를 확인했습니다.');}finally{el.disabled=false;}}
 else if(a==='go'){filter='all';term='';dept='';page=1;location.hash=el.dataset.view;}
 else if(a==='logout'){const result=await api('/auth/logout',{});location.assign(result.logout_url);}
 else if(a==='retry-job'){await api(`/api/jobs/${encodeURIComponent(id)}/retry`,{});await load();await render();toast('재시도 작업을 접수했습니다.');}
 else if(a==='refresh'){await load();await render();toast('로컬 저장 데이터를 새로 불러왔습니다.');}
 else if(a==='metric'){filter=el.dataset.filter;term='';dept='';page=1;location.hash='ledger';}
 else if(a==='filter'){filter=el.dataset.filter;page=1;await render();}
 else if(a==='clear-filters'){term='';dept='';filter='all';page=1;await render();}
 else if(a==='page'){page=Number(el.dataset.page);$('#ledger-results').innerHTML=ledgerResults();}
 else if(a==='history-page'){page=Number(el.dataset.page);await render();}
 else if(a==='detail'){await load();detail(id);}
 else if(a==='change')changeForm(id,el.dataset.kind);
 else if(a==='pc')pcForm(id);
 else if(a==='event'){const h=state.history.find(h=>h.event_id===id);openDialog(dialogHeader(events[h.event_type]||h.event_type,h.event_id)+`<div class="dialog-form"><p>${esc(h.description)}</p><div class="dialog-info">${timeText(h.event_at_utc)} KST · ${esc(h.actor_upn)}<br>${esc(h.approval_id)} · ${esc(h.old_status||'접수 전')} → ${esc(h.new_status)}</div>${h.before?`<h3>변경 전 / 후</h3><div class="timeline-item"><pre>${esc(JSON.stringify({before:h.before,after:h.after},null,2))}</pre></div>`:'<p class="field-note">초기 샘플 이력에는 변경 전후 전체 값이 포함되지 않았습니다.</p>'}</div>`);}
 else if(a==='export'){const ids=currentView==='ledger'?filtered().map(r=>r.approval_id):state.approvals.map(r=>r.approval_id);if(!ids.length)return toast('내보낼 항목이 없습니다.');const link=document.createElement('a');link.href='/api/export.csv?ids='+encodeURIComponent(ids.join(','));link.download='usb-ledger-demo.csv';link.click();toast(`${ids.length}건의 가상 데이터를 CSV로 내보냈습니다.`);}
 else if(a==='fill-sample'){const linked=$('[name=sample_group_key]',$('#register-form'));if(linked)linked.remove();const values={user_display_name:'김샘플',user_upn:'sample.new@example.invalid',department:'정보보안팀',usb_serial:'SAMPLE-NEW-0001',usb_name:'가상 보안 USB 신규',permission:'read_write',bitlocker_state:'encrypted',valid_from_date:state.reference_date,valid_until_date:new Date(new Date(state.reference_date+'T00:00:00Z').getTime()+30*86400000).toISOString().slice(0,10),approval_document_no:'SAMPLE-GW-2026-0041',request_reason:'승인된 가상 업무자료 반출 테스트'};for(const [key,value]of Object.entries(values))$(`[name="${key}"]`,$("#register-form")).value=value;toast('가상 등록 예시를 채웠습니다.');}
 else if(a==='publish')openDialog(dialogHeader('정책 변경 모의 게시')+`<form id="publish-form" class="dialog-form"><div class="dialog-info">허용 변경 ${plan.pending.length}건, 회수 ${plan.withdrawals.length}건의 배포 작업을 접수합니다.<br>작업자가 모의 게시한 뒤에도 단말 확인은 별도 대기 상태입니다. 실제 Intune에는 요청을 보내지 않습니다.</div><div class="form-error" role="alert"></div><div class="form-actions"><button type="button" data-action="close">취소</button><button class="primary" type="submit">모의 게시 실행</button></div></form>`);
}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;e.preventDefault();try{await doAction(el);}catch(error){if(!await queuedNotice(error))toast(error.message,true);}});
document.addEventListener('input',e=>{if(e.target.id==='search'){term=e.target.value;page=1;$('#ledger-results').innerHTML=ledgerResults();}if(e.target.id==='history-search'){const input=e.target;const pos=input.selectionStart;historyTerm=input.value;page=1;$('#main').innerHTML=historyView();$('#history-search').focus();$('#history-search').setSelectionRange(pos,pos);}});
document.addEventListener('change',e=>{if(e.target.id==='dept'){dept=e.target.value;page=1;$('#ledger-results').innerHTML=ledgerResults();}});
document.addEventListener('submit',async e=>{const form=e.target;if(!['register-form','change-form','pc-form','publish-form','lookup-form','sample-form'].includes(form.id))return;e.preventDefault();const button=$('button[type=submit]',form);const errorEl=form.id==='register-form'?$('#register-error'):$('.form-error',form);errorEl.textContent='';button.disabled=true;try{const data=Object.fromEntries(new FormData(form));let result;
 if(form.id==='sample-form'){await api(`/api/sample-directory/${encodeURIComponent(form.dataset.id)}`,{...data,action:form.dataset.kind});dialog.close();await render();toast('샘플 그룹 멤버 변경을 Graph 재조회로 확인했습니다.');return;}
 if(form.id==='register-form'&&!data.sample_group_key)delete data.sample_group_key;
 if(form.id==='lookup-form'){result=await api('/api/lookups/evaluate',data);$('#lookup-result').innerHTML=liveLookupResult(result);toast(result.decision==='pending'?'조회 결과를 확인했습니다. 판정은 보류되었습니다.':'조회와 판정 결과를 확인했습니다. 정책은 변경하지 않았습니다.');}
 else if(form.id==='register-form'){result=await api('/api/approvals',data);await load();location.hash='ledger';filter='all';term=result.usb_serial;dept='';page=1;await render();toast('승인 정보가 등록됐습니다. 식별 검증 대기 상태입니다.');detail(result.approval_id);}
 else if(form.id==='change-form'){result=await api(`/api/approvals/${form.dataset.id}/${form.dataset.kind}`,{...data,revision:Number(form.dataset.revision)});await load();await render();detail(result.approval_id);toast('변경을 로컬에 기록했습니다.');}
 else if(form.id==='pc-form'){await api(`/api/pcs/${form.dataset.id}`,{...data,revision:Number(form.dataset.revision)});dialog.close();await load();await render();toast('PC 분류를 기록했습니다. 실제 그룹 반영은 대기 상태입니다.');}
 else {result=await api('/api/deployment/simulate',{fingerprint:plan.fingerprint});dialog.close();await load();await render();toast(result.job?`${result.job.item_count}건 배포 작업 접수 · 처리 대기`:'새로 처리할 변경이 없습니다.');}
 }catch(error){if(!await queuedNotice(error))errorEl.textContent=error.message;}finally{button.disabled=false;}});
window.addEventListener('hashchange',()=>{page=1;render().catch(e=>toast(e.message,true));});
dialog.addEventListener('click',e=>{if(e.target===dialog){const b=dialog.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)dialog.close();}});
load().then(render).catch(error=>{$('#main').innerHTML='<div class="empty"><strong>데이터를 불러오지 못했습니다.</strong>서버 연결과 설정을 확인한 후 새로 고침해 주세요.</div>';toast(error.message,true);});
function applyIdentity(){
 const user=identity.user;
 if(!user)return;
 const operator=document.querySelector('.operator');
 operator.innerHTML=`<span class="avatar">${esc(user.name.slice(0,1))}</span><span>${esc(user.name)}<small>${identity.mode==='entra'?'Entra SSO · '+(identity.can_write?'운영자':'조회자'):'데모 세션 · SSO 미연결'}</small></span>`;
 operator.title=user.username;
 const actions=document.querySelector('.top-actions');
 const old=document.querySelector('#logout-button');
 if(old)old.remove();
 if(identity.mode==='entra')actions.insertAdjacentHTML('beforeend','<button id="logout-button" class="subtle-button" data-action="logout">로그아웃</button>');
}
function applyPermissions(){
 if(!identity||identity.can_write)return;
 document.querySelector('nav [data-view="register"]').hidden=true;
 if(currentView==='register')document.querySelector('#main').innerHTML=header('register')+notice()+'<section class="panel"><div class="empty"><strong>조회 권한으로 로그인했습니다.</strong>등록·변경·게시에는 USB 운영자 역할이 필요합니다.</div></section>';
 document.querySelectorAll('[data-action="change"],[data-action="pc"],[data-action="publish"],[data-action="fill-sample"],[data-action="retry-job"],[data-action="sample-change"],[data-action="sample-expiry"],[data-action="pair-publish"],[data-action="sample-sync"],[data-action="fill-linked-sample"],[data-action="go"][data-view="register"]').forEach(el=>{el.disabled=true;el.title='USB 운영자 권한이 필요합니다.';});
}

