function fillLinkedSample(){
 const r=sampleMappings.find(r=>r.source_approval_id===$('#sample-account').value);if(!r)return;
 const today=new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Seoul'});
 const values={user_display_name:r.name,user_upn:r.source_upn,department:r.department,
 usb_serial:'SAMPLE-GROUP-FLOW-ONLY-20261028',usb_name:'그룹 연결 검증용 공통 샘플 USB',permission:'read_only',bitlocker_state:'unknown',
 valid_from_date:today,valid_until_date:today,approval_document_no:'SAMPLE-GROUP-'+Date.now(),request_reason:'원장 승인·연장·회수와 실제 샘플 그룹 연결 검증'};
 const form=$('#register-form');for(const [key,value]of Object.entries(values))$(`[name="${key}"]`,form).value=value;
 let hidden=$('[name="sample_group_key"]',form);if(!hidden){hidden=document.createElement('input');hidden.type='hidden';hidden.name='sample_group_key';form.appendChild(hidden);}hidden.value=r.source_approval_id;
 toast('실제 샘플 그룹 연결 입력을 채웠습니다. 승인 정보를 등록해 주세요.');
}
setInterval(async()=>{
 if(!state?.sample_group_links?.some(l=>['queued','processing','retry_pending'].includes(l.state))||(dialog.open&&!dialog.dataset.groupLedgerId)||jobRefreshBusy)return;
 if(!['ledger','sample','history','deployment'].includes(currentView))return;
 jobRefreshBusy=true;try{const detailId=dialog.dataset.groupLedgerId;await load();if(dialog.open&&detailId)detail(detailId);else await render();}catch(error){toast(error.message,true);}finally{jobRefreshBusy=false;}
},5000);

function jobsPanel(){
 const jobStatus={queued:['처리 대기','blue'],processing:['처리 중','purple'],retry_wait:['자동 재시도 대기','amber'],succeeded:['모의 게시 완료','green'],dead_letter:['확인 필요','red'],superseded:['원장 변경 · 재검토','']};
 const jobs=jobsState?.jobs||[];
 const worker=jobsState?.runtime?.worker;
 const expiry=jobsState?.runtime?.expiry;
 return `<section class="panel" id="jobs-panel"><div class="panel-head"><div><h2>처리 작업<span class="section-count">${jobs.length}</span></h2><p>작업은 자동으로 처리됩니다. 모의 게시와 단말 확인은 별도입니다.</p></div><span class="badge blue">로컬 Function 연결</span></div><div class="table-wrap"><table><thead><tr><th>작업 / 요청자</th><th>유형 / 대상</th><th>처리 상태</th><th>시도</th><th>최근 결과</th><th></th></tr></thead><tbody>${jobs.slice(0,20).map(j=>`<tr><td><span class="mono">${esc(j.id)}</span><span class="cell-sub">${esc(j.requester)}</span></td><td>${j.kind==='expiry'?'만료 회수':'허용 · 회수 게시'}<span class="cell-sub">${j.item_count}건</span></td><td>${badge(j.status,jobStatus)}</td><td>${j.attempts} / ${j.max_attempts}</td><td class="history-desc">${esc(j.error|| (j.status==='succeeded'?'게시 완료 · 단말 별도':j.status==='queued'?'작업 접수 완료':'—'))}</td><td>${['dead_letter','retry_wait'].includes(j.status)?`<button class="row-button" data-action="retry-job" data-id="${esc(j.id)}">재시도</button>`:''}</td></tr>`).join('')||'<tr><td colspan="6"><div class="empty">접수된 작업이 없습니다.</div></td></tr>'}</tbody></table></div><div class="callout">최근 작업 확인 ${worker?timeText(worker.last_run_at):'대기'} · 만료 확인 ${expiry?timeText(expiry.last_run_at):'대기'} · 모의 정책 스냅샷 ${jobsState?.policy?.version?.slice(0,12)||'없음'}</div></section>`;
}
setInterval(async()=>{
 if(currentView!=='deployment'||dialog.open||jobRefreshBusy||!jobsState?.jobs?.some(j=>['queued','processing','retry_wait'].includes(j.status)))return;
 jobRefreshBusy=true;
 try{await load();await render();if(!jobsState?.jobs?.some(j=>['queued','processing','retry_wait'].includes(j.status))){await load();await render();}}catch(error){toast(error.message,true);}finally{jobRefreshBusy=false;}
},4000);

function liveLookupPanel(){
 const today=new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Seoul'});
 return `<section class="panel"><div class="panel-head"><div><h2>실제 조회 · 판정</h2><p>Entra 사용자 → Defender USB 관측 → Intune PC → Fabric 승인 원장을 확인합니다. 정책 변경은 수행하지 않습니다.</p></div><span class="badge blue">읽기 전용</span></div><form id="lookup-form" class="dialog-form"><div class="form-grid"><label class="field"><span>실제 사용자 UPN</span><input name="user_upn" type="email" maxlength="150" required placeholder="user@company.com"></label><label class="field"><span>확인할 USB 시리얼</span><input name="usb_serial" maxlength="100" required placeholder="보유 중인 USB 시리얼"></label><label class="field"><span>요청 권한</span><select name="permission"><option value="read_only">읽기 전용</option><option value="read_write">읽기 · 쓰기</option></select></label><label class="field"><span>시작일</span><input name="valid_from_date" type="date" value="${today}" required></label><label class="field"><span>종료일</span><input name="valid_until_date" type="date" value="${today}" required></label></div><div class="form-error" role="alert"></div><div class="form-actions"><button type="submit" class="primary">실제 조회 · 판정 실행</button></div></form><div id="lookup-result" aria-live="polite"></div><div class="callout">아래 샘플 등록과 별도입니다. 권한 부족·관측 없음·샘플 원장은 검증 완료로 처리하지 않습니다. PC 암호화 정보로 USB 암호화를 판단하지 않습니다.</div></section>`;
}
function liveLookupResult(result){
 const labels={entra:'Entra 사용자',defender:'Defender USB 관측',intune:'Intune 관리 PC',fabric:'Fabric 원장'};
 const states={ok:'조회 성공',permission_denied:'조회 권한 부족',authentication_error:'인증 실패',not_found:'찾을 수 없음',not_queried:'선행 조회 필요',unavailable:'연결 불가',configuration_error:'연결 설정 필요',incomplete:'조회 범위 불완전',throttled:'요청 제한',service_error:'서비스 오류',identity_mismatch:'사용자 불일치'};
 const reasons={entra_account_disabled:'비활성 사용자',entra_account_state_unknown:'계정 활성 상태 확인 필요',policy_user_sid_unresolved:'정책용 사용자 SID 확인 필요',usb_not_observed_in_last_30_days:'최근 30일 USB 관측 없음',usb_serial_telemetry_unavailable:'관련 이벤트는 있으나 시리얼 식별 필드가 없어 확인 필요',usb_storage_class_unconfirmed:'USB 저장장치 여부 추가 확인 필요',usb_multiple_candidates:'USB 식별 후보 복수',usb_identity_incomplete:'USB VID/PID 또는 인스턴스 경로 부족',usb_bitlocker_evidence_required:'USB BitLocker 증거 별도 확인 필요',fabric_no_matching_real_valid_approval:'일치하는 실제 유효 승인 없음 · 샘플 제외',fabric_overlapping_approvals:'중복 승인 검토 필요',intune_devices_truncated:'Intune 조회 결과 추가 페이지 존재',no_recent_managed_and_classified_observed_pc:'최근 동기화·관측·예외 분류를 충족하는 PC 없음',requested_period_expired:'요청 기간 만료',requested_period_not_started:'요청 기간 시작 전'};
 const decision={pending:'판정 보류',blocked:'허용 조건 미충족',ready_for_review:'검토 가능한 조건 충족'};
 return `<div class="dialog-form"><h3>${decision[result.decision]||esc(result.decision)}</h3><p>${esc(result.note)}</p><div class="detail-grid">${Object.entries(result.sources).map(([name,v])=>`<div><small>${labels[name]||esc(name)}</small><strong>${states[v.status]||esc(v.status)}${v.http_status?' · HTTP '+v.http_status:''}</strong></div>`).join('')}</div><ul>${[...result.blockers,...result.pending_reasons].map(v=>`<li>${esc(reasons[v]||(v.includes(':')?(labels[v.split(':')[0]]||v.split(':')[0])+' · '+(states[v.split(':')[1]]||v.split(':')[1]):v))}</li>`).join('')}</ul><p>실제 유효 승인 ${result.eligible_approval_count===null?'미확인':result.eligible_approval_count+'건'} · 대상 PC ${result.eligible_pc_count===null?'미확인':result.eligible_pc_count+'대'} · 조회 ${timeText(result.checked_at_utc)} KST</p><details><summary>조회 근거 보기</summary><pre>${esc(JSON.stringify(result,null,2))}</pre></details></div>`;
}
